import { loadEnvConfig } from "@next/env";
import { defineConfig } from "drizzle-kit";
import { resolveDatabaseConfig, type Dialect } from "./src/server/db/config";

/**
 * Used by `npm run db:studio` (and drizzle-kit commands run by hand). It targets
 * whatever database the environment points to, exactly like the app does.
 * Migrations for all three dialects are generated by `npm run db:generate`.
 */
loadEnvConfig(process.cwd());
const db = resolveDatabaseConfig();

const kitDialect: Record<Dialect, "turso" | "mysql" | "postgresql"> = {
  sqlite: "turso",
  mysql: "mysql",
  postgres: "postgresql",
};

export default defineConfig({
  dialect: kitDialect[db.dialect],
  schema: `./src/server/db/schema/${db.dialect}.ts`,
  out: `./database/migrations/${db.dialect}`,
  dbCredentials: { url: db.url, authToken: db.authToken },
});
